from rules import resolve


def solve(data):
    return resolve(data)

import re


def _interval(value):
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return value[0], value[1]
    if type(value) is int:
        return value, value
    if isinstance(value, dict):
        return value.get("min"), value.get("max")
    return None, None


def _constraint(value):
    if value is None:
        return None, None
    if isinstance(value, dict):
        if "range" in value:
            return _interval(value["range"])
        if "min" in value or "max" in value:
            return value.get("min"), value.get("max")
        if "version" in value:
            return value["version"], value["version"]
        return None, None
    return _interval(value)


def _dependencies(deps, features):
    result = []

    def add(name, spec=None, low=None, high=None):
        if not isinstance(name, str):
            return
        if spec is not None:
            low, high = _constraint(spec)
        result.append((name, low, high))

    def one(dep):
        if isinstance(dep, str):
            match = re.fullmatch(
                r"\s*([^\s<>=!@]+)\s*(>=|<=|==|=|>|<|@)\s*(-?\d+)\s*", dep
            )
            if not match:
                add(dep.strip())
                return
            name, op, raw = match.groups()
            number = int(raw)
            if op in ("=", "==", "@"):
                add(name, low=number, high=number)
            elif op == ">=":
                add(name, low=number)
            elif op == "<=":
                add(name, high=number)
            elif op == ">":
                add(name, low=number + 1)
            else:
                add(name, high=number - 1)
        elif isinstance(dep, dict):
            feature = dep.get("feature")
            if feature is not None and feature != "" and feature not in features:
                return
            name = dep.get("name", dep.get("package"))
            if name is not None:
                spec = dep.get("range", dep.get("version"))
                if spec is not None:
                    add(name, spec)
                else:
                    add(name, low=dep.get("min"), high=dep.get("max"))
            else:
                for dep_name, spec in dep.items():
                    if dep_name != "feature":
                        add(dep_name, spec)
        elif isinstance(dep, (list, tuple)) and dep:
            if len(dep) == 2:
                add(dep[0], dep[1])
            elif len(dep) >= 3:
                add(dep[0], low=dep[1], high=dep[2])
            else:
                add(dep[0])

    if isinstance(deps, dict):
        for name, spec in deps.items():
            add(name, spec)
    elif isinstance(deps, (list, tuple, set)):
        for dep in deps:
            one(dep)
    elif deps is not None:
        one(deps)
    return result


def _acyclic(graph):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[node] = 1
        for target in graph.get(node, ()):
            if not visit(target):
                return False
        state[node] = 2
        return True

    return all(visit(node) for node in graph)


def resolve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    raw_features = data.get("features", [])
    if raw_features is None:
        features = []
    elif isinstance(raw_features, (list, tuple, set)):
        features = list(raw_features)
    else:
        features = [raw_features]

    names = sorted(packages, key=str)
    rows_by_name = {}
    for name in names:
        rows = packages.get(name, [])
        rows_by_name[name] = [
            row for row in rows
            if isinstance(row, dict) and type(row.get("version")) is int
        ]

    required = {}
    for name, interval in roots.items():
        low, high = _interval(interval)
        required.setdefault(name, []).append((low, high))

    def valid(version, limits):
        return all(
            (low is None or version >= low)
            and (high is None or version <= high)
            for low, high in limits
        )

    best = None
    best_vector = None

    def visit(assigned, needs, graph):
        nonlocal best, best_vector
        pending = sorted(
            (name for name in needs if name not in assigned), key=str
        )
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = dict(assigned)
            return

        name = pending[0]
        if name not in rows_by_name:
            return

        forbidden = blocked.get(name, ())
        if type(forbidden) is int:
            forbidden = (forbidden,)
        elif forbidden is None:
            forbidden = ()
        try:
            forbidden = set(forbidden)
        except TypeError:
            forbidden = {forbidden}

        for row in sorted(
            rows_by_name[name], key=lambda item: item["version"], reverse=True
        ):
            version = row["version"]
            if version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue
            if not valid(version, needs[name]):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_needs = {key: list(limits) for key, limits in needs.items()}
            next_graph = {key: set(targets) for key, targets in graph.items()}
            next_graph.setdefault(name, set())
            possible = True

            for dep_name, low, high in _dependencies(
                row.get("deps", []), features
            ):
                next_needs.setdefault(dep_name, []).append((low, high))
                next_graph[name].add(dep_name)
                if dep_name in next_assigned and not valid(
                    next_assigned[dep_name], next_needs[dep_name]
                ):
                    possible = False
                    break

            if possible and _acyclic(next_graph):
                visit(next_assigned, next_needs, next_graph)

    visit({}, required, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}
